# Raup's theoretical morphospace of coiled shells (Raup 1966, J. Paleontol. 40:1178). Each shell is
# generated by revolving a circular generating curve about an axis while it grows by W per whorl (whorl
# expansion rate) and slides along the axis by T (translation rate); D (distance from the axis, here 0.1)
# is held constant (wikibio.zoomorph.raup_shell). The grid spans W (columns, log-spaced) and T (rows).
# Shaded regions show approximately where real shells fall (after Raup 1966, 1967): coiled cephalopods
# (ammonoids, Nautilus) are planispiral (T = 0) with low W; gastropods have low W and positive T (turreted
# shells at high T); bivalves and brachiopods have very high W, so a valve is less than one whorl, and low
# T. Most of the space (high W with high T, for instance) is empty: geometrically possible shells that
# are not realised, which raises the question of functional, developmental or historical constraints.
import wikibio as bio
from wikibio import zoomorph as zm

P = bio.P
WS = [1.5, 2.5, 5, 10, 100, 10000]
WL = ["1.5", "2.5", "5", "10", "10²", "10⁴"]
TS = [0, 1, 2.5, 5]
C = 3.3  # cell size
X0, Y0 = 3.2, 2.0
fig, ax = bio.canvas(X0 + C * len(WS) + 0.6, Y0 + C * len(TS) + 1.6)


def cell(i, j):
    return X0 + C * (i + 0.5), Y0 + C * (j + 0.5)


REG = [("Cephalopoda (coiled)", "dna", (0, 2), (0, 0), "below"), ("Gastropoda", "positive", (0, 2), (1, 3), "above"),
       ("Bivalvia, Brachiopoda", "antibody", (3, 5), (0, 0), "below"), ("Bivalvia (few)", "antibody", (3, 5), (1, 1), "above")]
for name, tok, (i0, i1), (j0, j1), where in REG:
    x0, y0 = X0 + C * i0 + 0.12, Y0 + C * j0 + 0.12
    w, h = C * (i1 - i0 + 1) - 0.24, C * (j1 - j0 + 1) - 0.24
    bio.box(ax, (x0 + w / 2, y0 + h / 2), w, h, token=tok, radius=0.4, lw=0.8, zorder=1)
    ax.patches[-1].set_facecolor(P.mix(P.fill(tok), P.surface(), 0.78 if P.is_dark() else 0.6))
    ty = y0 + 0.28 if where == "below" else y0 + h - 0.28
    bio.label(ax, (x0 + 0.2, ty), name, size="tiny", bold=True, ha="left", color=P.edge(tok) if not P.is_dark() else P.fill(tok))
for i, W in enumerate(WS):
    for j, T in enumerate(TS):
        x, y = cell(i, j)
        elev = 80 if T == 0 else (34 if W >= 10 else 10)
        zm.raup_shell(ax, (x, y), C * 0.62, W=W, D=0.1, T=T, elev=elev, n_theta=140, n_phi=18, z=5)
# axes
for i, lab in enumerate(WL):
    bio.label(ax, (cell(i, 0)[0], Y0 - 0.3), lab, size="small", va="top")
for j, T in enumerate(TS):
    bio.label(ax, (X0 - 0.3, cell(0, j)[1]), f"{T:g}", size="small", ha="right")
bio.label(ax, (X0 + C * len(WS) / 2, Y0 - 1.1), "W, whorl expansion rate per revolution (log scale)", size="normal", va="top")
bio.label(ax, (X0 - 1.5, Y0 + C * len(TS) / 2), "T, translation along the axis", size="normal", rotation=90)
bio.label(ax, (X0 + C * len(WS) / 2, Y0 + C * len(TS) + 0.9), "Raup's coiling morphospace (D = 0.1)", size="title", bold=True)
